import numpy as np, csv, collections, math, json
from math import erf, sqrt
C=2.955; N=2000
key=lambda r:(float(r['lr']),int(r['batch']),r['sched'],float(r['init_scale']),r['precision'])
def load():
    man=list(csv.DictReader(open('manifest.csv')))
    res=list(csv.DictReader(open('results.csv')))
    ml=collections.Counter(key(r) for r in man)
    rl=collections.defaultdict(list)
    for r in res: rl[key(r)].append(float(r['val_loss']))
    return ml,{k:np.array(rl[k]) for k in ml}
Phi=lambda z:0.5*(1+erf(z/sqrt(2)))
vPhi=np.vectorize(Phi)

def joint_fit(ml,data,verbose=False):
    """Joint MLE: n_k ~ Bin(N,(1-p_b)Phi(z_k)), x|observed ~ TN. Phi^n cancels."""
    cells=sorted(ml); batches=sorted({k[1] for k in cells})
    n={k:len(data[k]) for k in cells}
    S={k:data[k].sum() for k in cells}; SS={k:(data[k]**2).sum() for k in cells}
    # init
    mu={k:(data[k].mean() if n[k]>0 else C+0.2) for k in cells}
    sig=0.09; q={b:0.9 for b in batches}  # q=1-p
    def nll_mu(k,m,sig,qb):
        z=(C-m)/sig; P=Phi(z); s=qb*P
        val=(SS[k]-2*m*S[k]+n[k]*m*m)/(2*sig*sig)+n[k]*math.log(sig)
        rest=N-n[k]
        val-= n[k]*math.log(qb)+ (rest*math.log(max(1-s,1e-300)))
        return val
    def golden(f,lo,hi,it=80):
        for _ in range(it):
            a=lo+(hi-lo)*0.382; b=lo+(hi-lo)*0.618
            if f(a)<f(b): hi=b
            else: lo=a
        return 0.5*(lo+hi)
    for it in range(40):
        for k in cells:
            mu[k]=golden(lambda m:nll_mu(k,m,sig,q[k[1]]),mu[k]-0.3,mu[k]+0.3)
        # q_b: maximize sum n log q + (N-n) log(1-q P)
        for b in batches:
            ks=[k for k in cells if k[1]==b]
            def f(qb): return -sum(n[k]*math.log(qb)+(N-n[k])*math.log(1-qb*Phi((C-mu[k])/sig)) for k in ks)
            q[b]=golden(f,0.3,0.999)
        sig=golden(lambda s:sum(nll_mu(k,mu[k],s,q[k[1]]) for k in cells),0.05,0.15)
    return mu,sig,q

if __name__=='__main__':
    ml,data=load()
    mu,sig,q=joint_fit(ml,data)
    print('sigma',sig,'q',q)
    for k in sorted(ml): print(k,len(data[k]),'mu=%.4f'%mu[k],'Pg=%.4f'%(1-Phi((C-mu[k])/sig)))
    json.dump({'sigma':sig,'q':{str(b):v for b,v in q.items()},'mu':{repr(k):v for k,v in mu.items()}},open('joint.json','w'))
